// Actual TowerGame/DdaBattleSession/SaveStore plus UnityShim; never a Unity-runtime claim.
using System;using System.IO;using System.Linq;using System.Reflection;using System.Threading;using ReversalTower;using UnityEngine;
public static class DdaMonitorTests {
 static int n;static void Check(bool x,string s){if(!x)throw new Exception(s);n++;Console.WriteLine("PASS "+s);}
 static object Call(TowerGame g,string name,params object[] args)=>typeof(TowerGame).GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(g,args);
 static TowerGame Game(){var g=new TowerGame{save=new SaveData{tutorialOnboardingVersion=1,unlockedBoss=4}};typeof(TowerGame).GetField("sound",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(g,new Soundscape());return g;}
 static DdaMonitorFrame Latest(string dir,Func<DdaMonitorFrame,bool> test){var end=DateTime.UtcNow.AddSeconds(5);while(DateTime.UtcNow<end){try{var f=JsonUtility.FromJson<DdaMonitorFrame>(File.ReadAllText(Path.Combine(dir,"latest.json")));if(test(f))return f;}catch(IOException){}Thread.Sleep(5);}throw new Exception("Background publisher did not reach expected sequence");}
 static bool Sequence(string dir,long expected){var end=DateTime.UtcNow.AddSeconds(5);while(DateTime.UtcNow<end){try{using(var json=System.Text.Json.JsonDocument.Parse(File.ReadAllText(Path.Combine(dir,"latest.json"))))if(json.RootElement.GetProperty("sequence").GetInt64()==expected)return true;}catch(IOException){}Thread.Sleep(5);}return false;}
 public static int Main(string[] args){string root=args.Length>0?Path.GetFullPath(args[0]):Path.Combine(Path.GetTempPath(),"dda-monitor-test-"+Guid.NewGuid().ToString("N"));if(Directory.Exists(root)&&Directory.EnumerateFileSystemEntries(root).Any())throw new Exception("New isolated output required");Directory.CreateDirectory(root);SaveStore.UseIsolatedRoot(Path.Combine(root,"save"));
 try{
 foreach(var t in new[]{typeof(DdaMonitorFrame),typeof(DdaMonitorAttack),typeof(DdaMonitorPattern),typeof(DdaMonitorTutorial),typeof(DdaMonitorSelection)})Check(Attribute.IsDefined(t,typeof(SerializableAttribute)),"Unity JSON DTO explicitly serializable "+t.Name);
 var g=Game();g.StartBattle(0);g.PublishDdaMonitor("snapshot");Check(!Directory.Exists(Path.Combine(root,"DdaLive")),"diagnostic output defaults OFF");string diag=Path.Combine(root,"diagnostics");g.StartDdaMonitor(diag);var sink=(DdaMonitorSink)typeof(TowerGame).GetField("ddaMonitor",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(g);g.PublishDdaMonitor("snapshot");var f=Latest(sink.DirectoryPath,x=>x.sequence>=1);Check(f.origin=="headless-fixture"&&f.schema=="tower.dda.live/1","headless output never claims to be actual Unity");Check(f.sessionId==sink.SessionId&&f.runId==g.BossPatterns.DiagnosticSession,"explicit publisher session and battle run identities");Check(f.dda&&f.patterns.Count==g.stats.Count,"actual enabled assignment table exported");
 string before=JsonUtility.ToJson(g.save);g.BossPatterns.BeginPattern(g.spec.patterns[0]);f=Latest(sink.DirectoryPath,x=>x.kind=="attack-applied");var live=g.DdaSnapshot(false);Check(f.hasAttack&&f.attack.level==live.level&&f.attack.windup==live.windup&&f.attack.damage==live.damage&&f.attack.cooldown==live.cooldown,"publisher equals actual F8 attack source");Check(live.uploadStatus=="미수집","snapshot publisher skips storage-status directory scan");Check(JsonUtility.ToJson(g.save)==before,"diagnostic capture does not update model or save");
 for(int i=0;i<5;i++){g.playerInv=0;g.parryAge=.1f;g.PlayerHit(1,true,"cleave",g.boss.x);}g.PublishDdaMonitor("snapshot");f=Latest(sink.DirectoryPath,x=>x.patterns.Any(p=>p.id=="cleave"&&p.parries==5));Check(f.patterns.Single(p=>p.id=="cleave").opportunities==5,"actual parry observations exported");g.current=null;g.PublishDdaMonitor("idle");f=Latest(sink.DirectoryPath,x=>x.kind=="idle");Check(!f.hasAttack&&f.attack==null,"finished attack is not presented as current");
 g.BossPatterns.SelectPattern(4);g.PublishDdaMonitor("snapshot");f=Latest(sink.DirectoryPath,x=>x.selection.Count>0);Check(f.selection.Any(x=>x.selected)&&Math.Abs(f.selection.Sum(x=>x.probability)-1)<.0001,"actual weighted decision evidence exported");
 g.DamageBoss(g.bossHp);f=Latest(sink.DirectoryPath,x=>x.kind=="battle-ended");Check(f.phase=="result"&&!f.hasAttack&&f.clear,"settlement exports result and clears current attack");Check(f.learning.patterns.Any(x=>x.learned&&x.aDelta>0)&&f.battleId==g.result.battleId,"actual learning trace and persistent battle ID linked");string original=g.save.cloudPlayerId;Check(!File.ReadAllText(Path.Combine(sink.DirectoryPath,"latest.json")).Contains(original),"profile identity excluded from wire payload");
 g.ReturnLobby();g.StartTutorial(true);g.Tutorial.Tick(20,false);for(int i=0;i<6;i++)g.Tutorial.Acknowledge();g.Tutorial.Acknowledge();g.Tutorial.Tick(3,false);g.PublishDdaMonitor("tutorial");f=Latest(sink.DirectoryPath,x=>x.phase=="tutorial");Check(f.tutorial!=null&&f.tutorial.active==3&&f.tutorial.explanation==20&&f.tutorial.group==g.Tutorial.Preview().group,"actual tutorial preview and separated clocks exported");Check(f.learning==null&&f.patterns.Count==0,"tutorial never exported as boss learning");Check(f.runId!=f.diagnosticSession&&f.runId.Length==32,"tutorial has a separate run identity");g.ExitTutorial();g.StartBattle(0);g.save.dda=false;g.Abandon();g.PublishDdaMonitor("after-abandon");f=Latest(sink.DirectoryPath,x=>x.kind=="after-abandon");Check(f.abandoned&&f.learning.patterns.All(x=>!x.learned),"abandoned battle learning exclusion is visible");g.ReturnLobby();g.save.dda=false;g.StartBattle(0);g.PublishDdaMonitor("off-battle");f=Latest(sink.DirectoryPath,x=>x.kind=="off-battle");Check(!f.dda&&f.patterns.All(x=>x.level==0),"OFF battle remains fixed zero in monitor");string offModel=JsonUtility.ToJson(g.save.learning);g.DamageBoss(g.bossHp);Check(offModel==JsonUtility.ToJson(g.save.learning),"OFF settlement still does not train");
 var timing=new double[200];for(int i=0;i<timing.Length;i++){var timer=System.Diagnostics.Stopwatch.StartNew();g.PublishDdaMonitor("snapshot");timer.Stop();timing[i]=timer.Elapsed.TotalMilliseconds*1000;}Array.Sort(timing);File.WriteAllText(Path.Combine(root,"publisher-benchmark.json"),"{\"samples\":200,\"p50_microseconds\":"+timing[100].ToString(System.Globalization.CultureInfo.InvariantCulture)+",\"p95_microseconds\":"+timing[190].ToString(System.Globalization.CultureInfo.InvariantCulture)+",\"max_microseconds\":"+timing[199].ToString(System.Globalization.CultureInfo.InvariantCulture)+",\"scope\":\"HEADLESS forced capture; not Unity frame impact\"}");
 Call(g,"StopDdaMonitor");f=Latest(sink.DirectoryPath,x=>!x.running);Check(f.kind=="game-stopped","graceful shutdown heartbeat is explicit");
 var bad=Game();string blocker=Path.Combine(root,"not-directory");File.WriteAllText(blocker,"fixture");string state=JsonUtility.ToJson(bad.save);bad.StartDdaMonitor(blocker);Check(state==JsonUtility.ToJson(bad.save),"failed opt-in never changes save state");bad.StartBattle(0);Check(bad.mode==ScreenMode.Battle,"game continues after diagnostic setup failure");
 using(var bound=new DdaMonitorSink(Path.Combine(root,"bounds"))){var gate=typeof(DdaMonitorSink).GetField("gate",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(bound);lock(gate){for(int i=0;i<100;i++)bound.Offer("{\"sequence\":"+i+"}",true);Check(bound.Dropped>=68,"important event queue is bounded at 32");}Check(!bound.Offer(new string('x',DdaMonitorSink.MaxPacketBytes+1),true),"oversized diagnostic packets rejected");}
 using(var limit=new DdaMonitorSink(Path.Combine(root,"limit"))){limit.Offer("{\"sequence\":1}",true);Check(Sequence(limit.DirectoryPath,1),"bounded history fixture ready");using(var stream=new FileStream(Path.Combine(limit.DirectoryPath,"events.jsonl"),FileMode.OpenOrCreate))stream.SetLength(DdaMonitorSink.MaxHistoryBytes);limit.Offer("{\"sequence\":2}",true);Check(Sequence(limit.DirectoryPath,2),"latest updates after archive fills");var end=DateTime.UtcNow.AddSeconds(2);while(!limit.HistoryLimitReached&&DateTime.UtcNow<end)Thread.Sleep(5);Check(limit.HistoryLimitReached&&new FileInfo(Path.Combine(limit.DirectoryPath,"events.jsonl")).Length==DdaMonitorSink.MaxHistoryBytes,"history stops at 16MiB without deleting records");}
 using(var order=new DdaMonitorSink(Path.Combine(root,"order"))){var gate=typeof(DdaMonitorSink).GetField("gate",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(order);lock(gate){order.Offer("{\"sequence\":1}",false);order.Offer("{\"sequence\":2}",true);}Check(Sequence(order.DirectoryPath,2),"important event cannot be overwritten by an older coalesced snapshot");Directory.Delete(order.DirectoryPath,true);order.Offer("{\"sequence\":3}",true);var end=DateTime.UtcNow.AddSeconds(2);while(order.WriteErrors==0&&DateTime.UtcNow<end)Thread.Sleep(5);Check(order.WriteErrors>0,"background I/O failure recorded without game exception");}
 Console.WriteLine("DDA_MONITOR_PASS "+n+" HEADLESS; fixture output "+diag);return 0;
 }finally{SaveStore.UseIsolatedRoot(null);}}
}
